void boardInit()
{
  // enable interrupts
  __enable_irq();

  ledInit();
  boardInitModulePorts();

  pwrInit();
  delaysInit();
  timersInit();

  usbChargerInit();
  gpio_set(LED_BLUE_GPIO);

  ExtFLASH_InitRuntime();

  // register internal & external FLASH for UF2
  flashRegisterDriver(FLASH_BANK1_BASE, BOOTLOADER_SIZE, &stm32_flash_driver);
  flashRegisterDriver(QSPI_BASE, QSPI_FLASH_SIZE, &extflash_driver);

  usbInit();

  rgbLedInit();
  led_strip_off();

#if !defined(DEBUG_SEGGER_RTT)

  static uint32_t usbchgstatus=0;

  // This is needed to prevent radio from starting when usb is plugged to charge
  if (usbPlugged()) {
    while (usbPlugged() && !pwrPressed()) {//charging loop
      delay_ms(500);
      USBCharger(usbchgstatus);
      if (IS_UCHARGER_ACTIVE())  {
        /* code */
        ledRed();
        usbchgstatus=0;
      }
      else{
        ledGreen();
        usbchgstatus++;
      }
    }
    if (!pwrPressed()) {
      pwrOff();
      // Wait power to drain
      while (true) {
      }
    }
  }
#endif

  rgbLedInit();
  led_strip_off();

  keysInit();
  switchInit();
  rotaryEncoderInit();
  // touchPanelInit();
  audioInit();
  adcInit(&_adc_driver);
  hapticInit();

  rtcInit(); // RTC must be initialized before rambackupRestore() is called
}

TEST_P(AiProtocolManagerResponseIntegrationTest, ResponseOnlyModeDoesNotHoldRequestHeaders) {
  config_helper_.prependFilter(R"EOF(
name: envoy.filters.http.ai_protocol_manager
typed_config:
  "@type": type.googleapis.com/envoy.extensions.filters.http.ai_protocol_manager.v3.AiProtocolManager
  response_handling:
    token_usage:
      include_unconfigured_routes: true
)EOF",
                               /*downstream=*/false);
  initialize();

  codec_client_ = makeHttpConnection(lookupPort("http"));
  auto encoder_decoder = codec_client_->startRequest(requestHeaders());
  request_encoder_ = &encoder_decoder.first;
  auto response = std::move(encoder_decoder.second);

  // Headers arrive upstream while the request body has not been sent: no hold.
  ASSERT_TRUE(fake_upstreams_[0]->waitForHttpConnection(*dispatcher_, fake_upstream_connection_));
  ASSERT_TRUE(fake_upstream_connection_->waitForNewStream(*dispatcher_, upstream_request_));
  ASSERT_TRUE(upstream_request_->waitForHeadersComplete());

  codec_client_->sendData(*request_encoder_, "{}", true);
  ASSERT_TRUE(upstream_request_->waitForEndStream(*dispatcher_));

  upstream_request_->encodeHeaders(responseHeaders("application/json"), false);
  upstream_request_->encodeData("{\"type\":\"message\",\"model\":\"claude-haiku-4-5\","
                                "\"usage\":{\"input_tokens\":5,\"output_tokens\":7}}",
                                true);
  ASSERT_TRUE(response->waitForEndStream());
  ASSERT_TRUE(response->complete());

  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_found"), 1);
  EXPECT_EQ(sumCounters("ai_protocol_manager.token_usage_partial"), 0);
}

void fill_binlog_system_columns(Block& out, const TabletSchema& binlog_schema,
                                uint32_t binlog_tso_cid, uint32_t binlog_lsn_cid,
                                uint32_t binlog_op_cid, const std::vector<int64_t>& lsn_ids,
                                const std::vector<int64_t>& operators, size_t num_rows) {
    std::vector<uint32_t> binlog_cids = {binlog_tso_cid, binlog_lsn_cid, binlog_op_cid};
    Block binlog_system_block = binlog_schema.create_block_by_cids(binlog_cids);
    {
        auto binlog_system_columns_guard = binlog_system_block.mutate_columns_scoped();
        auto& binlog_system_columns = binlog_system_columns_guard.mutable_columns();

        // The reader replaces this placeholder with the real commit_tso.
        IColumn* tso_col_ptr = binlog_system_columns[0].get();
        auto* tso_nullable_column = check_and_get_column<ColumnNullable>(tso_col_ptr);
        DCHECK(tso_nullable_column != nullptr);
        tso_nullable_column->insert_many_defaults(num_rows);

        // Auto-inc LSN keeps row order until the rowset is published.
        IColumn* lsn_col_ptr = binlog_system_columns[1].get();
        for (size_t i = 0; i < num_rows; i++) {
            assert_cast<ColumnInt64*>(lsn_col_ptr)->insert_value(lsn_ids.at(i));
        }

        // wrong op only happens under partial update, it is fixed by the
        // delete bitmap at publish
        const FieldType op_col_type = binlog_schema.column(binlog_op_cid).type();
        IColumn* op_col_ptr = binlog_system_columns[2].get();
        auto* op_nullable_column = check_and_get_column<ColumnNullable>(op_col_ptr);
        IColumn* op_nested_column = op_nullable_column != nullptr
                                            ? &op_nullable_column->get_nested_column()
                                            : op_col_ptr;
        CHECK(operators.size() >= num_rows) << operators.size() << " vs " << num_rows;
        CHECK(op_col_type == FieldType::OLAP_FIELD_TYPE_BIGINT)
                << "row binlog op column type must be BIGINT, actual="
                << static_cast<int>(op_col_type);
        auto* op_int64_column = assert_cast<ColumnInt64*>(op_nested_column);
        for (size_t i = 0; i < num_rows; i++) {
            op_int64_column->insert_value(operators[i]);
        }

        if (op_nullable_column != nullptr) {
            auto& op_null_map = op_nullable_column->get_null_map_data();
            for (size_t i = 0; i < num_rows; i++) {
                op_null_map.emplace_back(0);
            }
        }
    }
    size_t col_pos_in_block = 0;
    for (auto cid : binlog_cids) {
        out.replace_by_position(cid,
                                binlog_system_block.get_by_position(col_pos_in_block++).column);
    }
}

static bool ggml_sycl_should_use_topk_moe(const ggml_tensor * gating_op, const ggml_tensor * weights,
                                          const ggml_tensor * logits, const ggml_tensor * ids) {
    const int n_expert = ids->nb[1] / ids->nb[0];
    if ((n_expert & (n_expert - 1)) != 0 || n_expert > 512) {
        return false;
    }

    if (!ggml_is_contiguous(weights) || !ggml_is_contiguous(logits)) {
        return false;
    }

    if (gating_op->op == GGML_OP_SOFT_MAX) {
        float scale    = 1.0f;
        float max_bias = 0.0f;

        memcpy(&scale, (const float *) gating_op->op_params + 0, sizeof(float));
        memcpy(&max_bias, (const float *) gating_op->op_params + 1, sizeof(float));

        if (!ggml_is_contiguous(gating_op->src[0])) {
            return false;
        }
        if (scale != 1.0f || max_bias != 0.0f) {
            return false;
        }
        // don't fuse when masks or sinks are present
        if (gating_op->src[1] || gating_op->src[2]) {
            return false;
        }
    } else if (gating_op->op == GGML_OP_UNARY) {
        if (ggml_get_unary_op(gating_op) != GGML_UNARY_OP_SIGMOID) {
            return false;
        }
    }

    return true;
}

void ParseNotes(const QByteArray& Segment, SElfInfo& Info)
{
	int Pos = 0;
	while (Pos + (int)sizeof(Elf64_Nhdr) <= Segment.size())
	{
		// Elf32_Nhdr and Elf64_Nhdr are both three 32-bit words, so one shape
		// covers either class.
		Elf32_Nhdr Nhdr;
		memcpy(&Nhdr, Segment.constData() + Pos, sizeof(Nhdr));
		Pos += sizeof(Nhdr);

		const int NameSize = (int)((Nhdr.n_namesz + 3) & ~3u);
		const int DescSize = (int)((Nhdr.n_descsz + 3) & ~3u);

		if (NameSize < 0 || DescSize < 0 || Pos + NameSize + DescSize > Segment.size())
			break;

		const QByteArray Name(Segment.constData() + Pos, (int)qMin<quint32>(Nhdr.n_namesz ? Nhdr.n_namesz - 1 : 0, (quint32)NameSize));
		const QByteArray Desc(Segment.constData() + Pos + NameSize, (int)Nhdr.n_descsz);

		if (Name == "GNU" && Nhdr.n_type == NT_GNU_BUILD_ID)
		{
			Info.BuildId = QString::fromLatin1(Desc.toHex());
		}
		else if (Name == "FDO" && Nhdr.n_type == NT_FDO_PACKAGING_METADATA)
		{
			//
			// The descriptor is NUL terminated JSON; the trailing NUL and any
			// alignment padding have to come off before parsing.
			//
			const QJsonObject Package = QJsonDocument::fromJson(
				QByteArray(Desc.constData(), (int)qstrnlen(Desc.constData(), Desc.size()))).object();

			Info.PackageName = Package.value("name").toString();
			Info.PackageVersion = Package.value("version").toString();
			Info.PackageOs = Package.value("os").toString();
		}

		Pos += NameSize + DescSize;
	}
}

void mf_plus_merge_update(MfPlusData* base, const MfPlusData* fresh) {
    furi_check(base);
    furi_check(fresh);

    // Per-field overlay: copy only what `fresh` actually recovered, never clearing a field `base`
    // already had (see mf_plus.h for why a successful re-read can still come back with less).
    for(uint16_t block = 0; block < MF_PLUS_MAX_BLOCKS; block++) {
        if(mf_plus_is_block_read(fresh, block)) {
            mf_plus_set_block_read(base, block, &fresh->block[block]);
        }
    }
    for(uint8_t sector = 0; sector < MF_PLUS_MAX_SECTORS; sector++) {
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeA)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeA, &fresh->key_a[sector]);
        }
        if(mf_plus_is_key_found(fresh, sector, MfPlusKeyTypeB)) {
            mf_plus_set_key_found(base, sector, MfPlusKeyTypeB, &fresh->key_b[sector]);
        }
    }
    for(uint8_t type = 0; type < MfPlusAdminKeyNum; type++) {
        if(mf_plus_is_admin_key_found(fresh, type)) {
            mf_plus_set_admin_key_found(base, type, &fresh->admin_key[type]);
        }
    }
    for(uint8_t index = 0; index < MF_PLUS_CONFIG_BLOCK_NUM; index++) {
        if(mf_plus_is_config_block_read(fresh, index)) {
            mf_plus_set_config_block_read(base, index, &fresh->config_block[index]);
        }
    }
    if(fresh->signature_present) {
        memcpy(base->signature, fresh->signature, MF_PLUS_SIGNATURE_SIZE);
        base->signature_present = true;
    }
}
